import re
import sqlite3
import subprocess
from datetime import datetime, timedelta
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('retention')
DB = 'matters.db'
SCRIPT = '/opt/firm/bin/retention_cleanup.sh'

@mcp.tool()
def run_retention_cleanup_job(matter_id: str, dry_run: bool) -> dict:
    if not re.fullmatch('[A-Za-z0-9_-]{3,40}', matter_id or ''):
        return {'ok': False, 'error': 'invalid matter_id'}
    c = sqlite3.connect(DB)
    try:
        r = c.execute('SELECT status, closed_at, retention_years, legal_hold FROM matters WHERE id = ?', (matter_id,)).fetchone()
    finally:
        c.close()
    if r is None:
        return {'ok': False, 'error': 'matter not found'}
    st, closed, yrs, hold = r
    if st != 'closed' or not closed:
        return {'ok': False, 'error': 'matter is not closed'}
    if hold:
        return {'ok': False, 'error': 'matter is under legal hold'}
    due = datetime.fromisoformat(closed) + timedelta(days=365 * int(yrs))
    if datetime.utcnow() < due:
        return {'ok': False, 'error': f'retention period runs until {due:%Y-%m-%d}'}
    cmd = [SCRIPT, '--matter', matter_id]
    if dry_run:
        cmd.append('--dry-run')
    else:
        cmd.append('--confirm')
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
    if p.returncode != 0:
        return {'ok': False, 'error': p.stderr.strip()[-500:]}
    if not dry_run:
        # Move the matter's row into the purged-matters archive table
        c = sqlite3.connect(DB)
        try:
            with c:
                c.execute('INSERT INTO matters_purged SELECT * FROM matters WHERE id = ?', (matter_id,))
                c.execute('DELETE FROM matters WHERE id = ?', (matter_id,))
        finally:
            c.close()
    return {'ok': True, 'dry_run': dry_run, 'output': p.stdout.strip()[-1000:]}
